-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.profiles (
  id uuid not null,
  email text not null,
  name text,
  avatar_url text,
  created_at timestamp with time zone default now() not null,
  constraint profiles_pkey PRIMARY KEY (id),
  constraint profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint profiles_name_length CHECK (((name IS NULL) OR (char_length(name) <= 200)))
);

CREATE INDEX profiles_created ON public.profiles USING btree (created_at);

alter table public.profiles enable row level security;

create policy "read own profile" on public.profiles
  as permissive
  for select
  to authenticated
  using (((id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

create policy "update own name" on public.profiles
  as permissive
  for update
  to authenticated
  using (((id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check ((id = ( SELECT auth.uid() AS uid)));

grant select on table public.profiles to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.profiles to service_role;
